        delay = self.base_delay_ms * (2 ** attempt)
        noise = 1.0 + random.uniform(-self.jitter, self.jitter)
        return int(delay * noise)

    def wait(self, attempt: int) -> None:
        time.sleep(self.backoff_ms(attempt) / 1000.0)

